from __future__ import annotations

from typing import Any
from urllib.parse import urlparse, urlunparse

PROJECT_TYPE_MAIN = "main"
PROJECT_TYPE_SUB = "sub"
PROJECT_TYPE_STANDALONE = "standalone"

CONTEXT_KIND_BY_PROJECT_TYPE = {
    PROJECT_TYPE_SUB: "workspace",
    PROJECT_TYPE_MAIN: "workspace_management",
    PROJECT_TYPE_STANDALONE: "standalone",
}


def _path_parts(url: str) -> list[str]:
    parsed = urlparse(url.rstrip("/"))
    return [part for part in parsed.path.split("/") if part]


def _replace_path(url: str, parts: list[str]) -> str:
    parsed = urlparse(url.rstrip("/"))
    path = "/" + "/".join(parts) if parts else ""
    return urlunparse(parsed._replace(path=path))


def _cluster_id_path_parts(url: str) -> list[str]:
    """Cluster id path segment(s), stripping workspace name and ``/manage`` UI suffix."""
    parts = _path_parts(url)
    if parts and parts[-1] == "manage":
        parts = parts[:-1]
    if len(parts) >= 2:
        return parts[:1]
    return parts


def parse_status_response(response: Any) -> dict[str, Any] | None:
    """Return the primary status object from ``GET /api/status``."""
    if not isinstance(response, dict):
        return None
    statuses = response.get("statuses")
    if isinstance(statuses, list) and statuses:
        first = statuses[0]
        if isinstance(first, dict):
            return first
    if response.get("project_type") is not None:
        return response
    return None


def project_type_from_status(status: dict[str, Any] | None) -> str | None:
    if not status:
        return None
    project_type = status.get("project_type")
    return project_type if isinstance(project_type, str) else None


def context_kind_for_project_type(project_type: str | None) -> str | None:
    if not project_type:
        return None
    return CONTEXT_KIND_BY_PROJECT_TYPE.get(project_type)


def is_workspace_management(project_type: str | None) -> bool:
    return project_type == PROJECT_TYPE_MAIN


def is_workspace_project(project_type: str | None) -> bool:
    return project_type == PROJECT_TYPE_SUB


def is_standalone_project(project_type: str | None) -> bool:
    return project_type == PROJECT_TYPE_STANDALONE


def derive_management_cluster_url(cluster_url: str) -> str:
    """
    Derive the workspace-management API base from a workspace or management URL.

    Mage Pro serves the management API on the main project host (``project_type=main``),
    not on the ``/manage`` UI path.
    """
    parts = _cluster_id_path_parts(cluster_url)
    if not parts:
        return cluster_url.rstrip("/")
    return _replace_path(cluster_url, parts)


def _scheme_for_workspace_url(
    management_cluster_url: str,
    reference_cluster_url: str | None = None,
) -> str:
    """Pick URL scheme; never downgrade https to http when any reference uses https."""
    schemes: list[str] = []
    for url in (management_cluster_url, reference_cluster_url):
        if not url:
            continue
        scheme = urlparse(url.rstrip("/")).scheme
        if scheme:
            schemes.append(scheme)
    if "https" in schemes:
        return "https"
    if schemes:
        return schemes[0]
    return "https"


def derive_workspace_cluster_url(
    management_cluster_url: str,
    workspace_name: str,
    reference_cluster_url: str | None = None,
) -> str:
    """Build the workspace API base; path from management, scheme preserved from references."""
    parts = _cluster_id_path_parts(management_cluster_url)
    path_url = _replace_path(management_cluster_url, [*parts, workspace_name])
    scheme = _scheme_for_workspace_url(management_cluster_url, reference_cluster_url)
    parsed = urlparse(path_url.rstrip("/"))
    return urlunparse(parsed._replace(scheme=scheme))


def extract_workspace_name(cluster_url: str) -> str | None:
    """Infer workspace name from a workspace-scoped cluster URL path."""
    parts = _path_parts(cluster_url)
    if len(parts) >= 2 and parts[-1] != "manage":
        return parts[1]
    return None
